export interface Task {
  id: string;
  title: string;
  done: boolean;
}

export const STORAGE_KEY = 'ai-todo-tasks';

export function loadTasks(): Task[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item): item is Task => {
        return (
          typeof item === 'object' &&
          item !== null &&
          typeof (item as Task).id === 'string' &&
          typeof (item as Task).title === 'string' &&
          typeof (item as Task).done === 'boolean'
        );
      })
      .map((item) => ({ id: item.id, title: item.title, done: item.done }));
  } catch {
    return [];
  }
}

export function saveTasks(tasks: Task[]): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch {
    // ignore storage failures
  }
}
